  function renderFeedbackMedia(){const preview=$("feedbackMediaPreview");if(!preview)return;const revision=++feedbackPreviewRevision,files=feedbackMediaFiles;$("feedbackMediaTrigger")?.classList.toggle("limit-reached",files.length>=4);preview.hidden=!files.length;preview.innerHTML=files.map((file,index)=>{const isImage=file.type.startsWith("image/"),isVideo=file.type.startsWith("video/");return `<article class="feedback-media-item"><div class="feedback-media-thumbnail">${isImage?`<img data-feedback-preview="${index}" alt="${escapeHtml(file.name)}">`:`<span aria-hidden="true">${isVideo?"▶":"▤"}</span>`}</div><div><strong title="${escapeHtml(file.name)}">${escapeHtml(file.name)}</strong><small>${escapeHtml(bytes(file.size))}</small></div><button type="button" data-feedback-remove="${index}" title="${escapeHtml(t("feedbackRemoveMedia"))}" aria-label="${escapeHtml(t("feedbackRemoveMedia"))}">×</button></article>`}).join("");if(files.length)preview.insertAdjacentHTML("afterbegin",`<p class="feedback-media-count">${escapeHtml(t("feedbackSelectedMedia",{count:files.length}))}</p>`);files.forEach((file,index)=>{if(!file.type.startsWith("image/"))return;const reader=new FileReader();reader.addEventListener("load",()=>{if(revision!==feedbackPreviewRevision||feedbackMediaFiles[index]!==file)return;const image=preview.querySelector(`[data-feedback-preview="${index}"]`);if(image&&typeof reader.result==="string")image.src=reader.result});reader.readAsDataURL(file)})}
  function addFeedbackMedia(selectedFiles){resetFeedbackConsent();const input=$("feedbackMedia"),seen=new Set(feedbackMediaFiles.map(feedbackFileKey));let total=feedbackMediaFiles.reduce((sum,file)=>sum+file.size,0),rejected=false;for(const file of selectedFiles){const key=feedbackFileKey(file);if(seen.has(key))continue;if(feedbackMediaFiles.length>=4||total+file.size>20*1024*1024){rejected=true;continue}feedbackMediaFiles.push(file);seen.add(key);total+=file.size}input.value="";renderFeedbackMedia();if(rejected)toast(t("feedbackMediaTooLarge"),"error")}
  function removeFeedbackMedia(index){resetFeedbackConsent();feedbackMediaFiles.splice(index,1);renderFeedbackMedia()}
  function clearFeedbackFieldError(input,error){input.classList.remove("feedback-invalid");input.removeAttribute("aria-invalid");error.hidden=true}
  function showFeedbackFieldError(input,error){input.classList.remove("feedback-invalid");void input.offsetWidth;input.classList.add("feedback-invalid");input.setAttribute("aria-invalid","true");error.hidden=false}
  function validateFeedbackFields(){const emailInput=$("feedbackEmail"),issueInput=$("feedbackIssue"),emailError=$("feedbackEmailError"),issueError=$("feedbackIssueError"),email=emailInput.value.trim(),issue=issueInput.value.trim(),emailValid=email!==""&&emailInput.checkValidity(),issueValid=issue.length>=5;clearFeedbackFieldError(emailInput,emailError);clearFeedbackFieldError(issueInput,issueError);if(!emailValid)showFeedbackFieldError(emailInput,emailError);if(!issueValid)showFeedbackFieldError(issueInput,issueError);const firstInvalid=!emailValid?emailInput:!issueValid?issueInput:null;if(firstInvalid){firstInvalid.scrollIntoView({block:"center",behavior:"smooth"});firstInvalid.focus({preventScroll:true})}return {valid:emailValid&&issueValid,email,issue}}
  function feedbackFormData(validation,recipient,files){const form=new FormData(),subject=t("feedbackTitle"),body=`${t("yourEmail")}: ${validation.email}\n\n${t("problemDescription")}:\n${validation.issue}`;form.set("consent",String($("feedbackConsent").checked));form.set("consent_version","2026-09-03");form.set("issue",validation.issue);form.set("email",validation.email);form.set("recipient",recipient);form.set("locale",state.locale);form.set("subject",subject);form.set("body",body);files.forEach(file=>form.append("media",file,file.name));return form}
  let activeFeedbackUpload=null,feedbackUploadTimer=null,announcedFeedbackTicket="";
  function feedbackUploadStateKey(state){return {queued:"feedbackStateQueued",uploading:"feedbackStateUploading",retrying:"feedbackStateRetrying",paused:"feedbackStatePaused",failed:"feedbackStateFailed",completed:"feedbackStateCompleted",cancelled:"feedbackStateCancelled"}[state]||"feedbackStateQueued"}
  function renderFeedbackUpload(job){activeFeedbackUpload=job||null;const panel=$("feedbackUploadPanel");if(!job){panel.hidden=true;return}panel.hidden=false;const total=Number(job.total_bytes||0),uploaded=Number(job.uploaded_bytes||0),percent=job.state==="completed"?100:total?Math.max(0,Math.min(100,Math.round(uploaded/total*100))):0;$("feedbackUploadState").textContent=t(feedbackUploadStateKey(job.state));$("feedbackUploadPercent").textContent=`${percent}%`;$("feedbackUploadProgress").value=percent;const parts=job.total_parts?` · ${t("feedbackPartProgress",{current:job.current_part||0,total:job.total_parts})}`:"";$("feedbackUploadDetail").textContent=`${bytes(uploaded)} / ${bytes(total)}${parts}${job.state==="retrying"&&job.next_attempt_at?` · ${t("feedbackNextRetry",{time:new Date(job.next_attempt_at).toLocaleString(state.locale)})}`:""}`;$("pauseFeedbackUpload").hidden=job.state!=="uploading";$("resumeFeedbackUpload").hidden=job.state!=="paused";$("retryFeedbackUpload").hidden=job.state!=="failed";$("cancelFeedbackUpload").hidden=["completed","cancelled"].includes(job.state);updateFeedbackConsentControls();if(job.state==="completed"&&job.ticket_id&&announcedFeedbackTicket!==job.ticket_id){announcedFeedbackTicket=job.ticket_id;$("feedbackPackageName").textContent=job.ticket_id;openDialog($("feedbackPackageDialog"));toast(t("feedbackUploadReadyTitle"),"success")}clearTimeout(feedbackUploadTimer);if(["queued","uploading","retrying"].includes(job.state))feedbackUploadTimer=setTimeout(()=>loadFeedbackUpload(job.id),1500)}
  async function loadFeedbackUpload(id){try{renderFeedbackUpload(await api(`/feedback/uploads/${encodeURIComponent(id)}`))}catch(error){clearTimeout(feedbackUploadTimer);toast(friendlyError(error,"feedback"),"error")}}
  async function loadFeedbackUploads(){try{const result=await api("/feedback/uploads"),jobs=result.jobs||[],job=jobs.find(item=>!["completed","cancelled"].includes(item.state))||jobs.find(item=>item.state==="completed");if(job){if(job.state==="completed")announcedFeedbackTicket=job.ticket_id||"";renderFeedbackUpload(job)}}catch(_){} }
  async function feedbackUploadAction(action){if(!activeFeedbackUpload)return;const requiresConsent=["resume","retry"].includes(action);if(requiresConsent&&!$("feedbackConsent").checked){toast(t("feedbackConsentRequired"),"error");return}try{renderFeedbackUpload(await api(`/feedback/uploads/${encodeURIComponent(activeFeedbackUpload.id)}/${action}`,{method:"POST",body:requiresConsent?JSON.stringify({consent:true,consent_version:"2026-09-03"}):undefined}));if(requiresConsent)resetFeedbackConsent()}catch(error){toast(friendlyError(error,"feedback"),"error")}}
  async function prepareFeedbackPackage(){if(feedbackSending)return;if(!$("feedbackConsent").checked){toast(t("feedbackConsentRequired"),"error");return}const validation=validateFeedbackFields(),recipient=$("feedbackRecipient").value,files=[...feedbackMediaFiles];if(!validation.valid){toast(t("feedbackIncomplete"),"error");return}if(files.length>4||files.reduce((sum,file)=>sum+file.size,0)>20*1024*1024){toast(t("feedbackMediaTooLarge"),"error");return}feedbackSending=true;updateFeedbackConsentControls();try{const job=await api("/feedback/upload",{method:"POST",body:feedbackFormData(validation,recipient,files)});renderFeedbackUpload(job);resetFeedbackConsent();toast(t("feedbackQueued"),"success")}catch(error){toast(friendlyError(error,"feedback"),"error")}finally{feedbackSending=false;updateFeedbackConsentControls()}}
  async function exportFeedbackLogs(){const button=$("exportFeedbackLogs");button.disabled=true;try{await downloadFile("/feedback/logs.json","diskcheck-support-logs.json");toast(t("feedbackLogsExported"),"success")}catch(error){toast(friendlyError(error),"error")}finally{button.disabled=false}}
  function friendlyError(error,context=""){if(error?.code==="FEEDBACK_CONSENT_REQUIRED")return t("feedbackConsentRequired");if(error?.code==="FEEDBACK_UPLOAD_FAILED"||error?.code==="FEEDBACK_UPLOAD_UNAVAILABLE"||context==="feedback")return t("feedbackUploadFailed");if(error?.code==="FEEDBACK_SEND_FAILED")return t("feedbackMailUnavailable");if(error?.code==="TOS_NOTIFICATION_FAILED")return t("notificationMailUnavailable");if(error?.code==="SCAN_RESULT_UNAVAILABLE")return t("scanResultUnavailable");if(error?.code==="SCAN_ACTION_REJECTED")return t("scanStateChanged");if(error?.code==="ADMIN_AUTH_REQUIRED")return t("sessionExpired");if(["HELPER_UNAVAILABLE","SMART_COLLECTION_FAILED","SCAN_JOB_NOT_FOUND"].includes(error?.code))return t("deviceUnavailable");if(error?.code==="SCAN_CREATE_BLOCKED")return t("scanCreateBlocked");if(error?.code==="GUARDIAN_SNAPSHOT_NOT_FOUND")return t("snapshotUnavailable");return t("loadFailed")}
  function toast(message,type=""){const element=$("toast");clearTimeout(element.hideTimer);element.textContent=message;element.className=`toast show ${type}`.trim();element.hideTimer=setTimeout(()=>{element.classList.remove("show","error","success","warning")},type==="error"?6500:3200)}
